const state=loadState(); let flashState=loadFlashState(); let selectedFrameworkNode='vision'; let studyGuideTopic='plan-purpose'; let studyGuideAnswers={}; try{studyGuideAnswers=JSON.parse(localStorage.getItem('mindplan-study-guide-v1')||'{}')}catch(e){} let page='home',previousPage='home',activeCase=null,step='intro',decisionIndex=0,answers={},planner={determinants:[],protective:[],pillars:[],indicator:'',numerator:'',denominator:'',dataSource:'',limitation:'',rationale:''},review=[];
