function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300)}
function cite(a){const c=a.citation||{};const ref=encodeURIComponent(JSON.stringify({title:a.title||'National Mental Health Strategic Plan 2019–2023',claim:a.claim||'',label:a.label||'source-says',printedPages:c.printedPages||'',pdfPages:c.pdfPages||'',verification:c.verificationStatus||c.verification||'',excerpt:a.excerpt||''}));return `<div class="citation"><strong>${esc(a.label==='source-says'?'Source says':a.label==='learning-interpretation'?'Learning interpretation':'Proposed learning item')}</strong> · <button type="button" class="citation-link" data-source-ref="${ref}">Printed p. ${esc(c.printedPages||'not specified')} · PDF p. ${esc(c.pdfPages||'not specified')} ↗</button>${c.verificationStatus||c.verification?`<br><span class="label-proposed">${esc(c.verificationStatus||c.verification)}</span>`:''}<br>${esc(a.claim||'')}</div>`}
function labelType(t){return t==='source-says'?'label-source':t==='learning-interpretation'?'label-interpretation':'label-proposed'}
function nav(p){if(p!==page)previousPage=page;page=p;document.querySelectorAll('.nav-item').forEach(b=>{const active=b.dataset.page===p;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});closeSearch();render();main.setAttribute('tabindex','-1');main.focus({preventScroll:true})}
function goBack(){if(page==='case'&&activeCase){const steps=['intro',...activeCase.decisionPoints.map(d=>d.id),'planner','review','debrief'];const i=steps.indexOf(step);if(i>0){step=steps[i-1];renderCase();return}nav('cases');return}nav(previousPage&&previousPage!==page?previousPage:'home')}
document.getElementById('backButton').addEventListener('click',goBack);
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}if(e.key==='Escape')closeSearch()});
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.page)));
document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('light');localStorage.setItem(THEME,document.body.classList.contains('light')?'light':'dark');document.getElementById('themeToggle').setAttribute('aria-label',document.body.classList.contains('light')?'Switch to dark mode':'Switch to light mode')});
if(localStorage.getItem(THEME)==='light')document.body.classList.add('light');
document.getElementById('caseCount').textContent=cases.length;
document.addEventListener('click',e=>{const b=e.target.closest('[data-source-ref]');if(b){try{openSource(JSON.parse(decodeURIComponent(b.dataset.sourceRef)))}catch(_){toast('Reference details unavailable.')}}});
const sourceDialog=document.getElementById('sourceDialog');let sourceOpener=null;document.getElementById('closeSourceDialog').addEventListener('click',()=>sourceDialog.close());sourceDialog.addEventListener('click',e=>{if(e.target.id==='sourceDialog')sourceDialog.close()});sourceDialog.addEventListener('close',()=>{if(sourceOpener&&sourceOpener.isConnected)sourceOpener.focus();sourceOpener=null});
const searchInput=document.getElementById('globalSearch'),searchResults=document.getElementById('searchResults');
function closeSearch(){if(!searchResults)return;searchResults.hidden=true;searchInput?.setAttribute('aria-expanded','false')}
function searchableText(v){if(v==null)return '';if(typeof v==='string'||typeof v==='number')return String(v);if(Array.isArray(v))return v.map(searchableText).join(' ');if(typeof v==='object')return Object.entries(v).map(([k,val])=>k+' '+searchableText(val)).join(' ');return ''}
const QUICKREF_ACRONYMS=[
['AO','Administrative Order'],['BHW','Barangay Health Worker'],['CHED','Commission on Higher Education'],['CHR','Commission on Human Rights'],['CSC','Civil Service Commission'],['CSO','Civil Society Organization'],['DepEd','Department of Education'],['DILG','Department of the Interior and Local Government'],['DOH','Department of Health'],['DOLE','Department of Labor and Employment'],['DPCB','Disease Prevention and Control Bureau'],['DSWD','Department of Social Welfare and Development'],['ECCD','Early Childhood Care and Development'],['ENCDD','Essential Non-Communicable Diseases Division'],['GIDA','Geographically Isolated and Disadvantaged Areas'],['HRH','Human Resources for Health'],['IRB','Internal Review Board'],['IRR','Implementing Rules and Regulations'],['JMC','Joint Memorandum Circular'],['LGU','Local Government Unit'],['MH','Mental Health'],['MHPSS','Mental Health and Psychosocial Support'],['MNS','Mental, Neurological, and Substance Abuse'],['MOP','Manual of Procedures'],['NBI','National Bureau of Investigation'],['NCMH','National Center for Mental Health'],['NGA','National Government Agency'],['NGO','Non-government Organization'],['PAP','Psychological Association of the Philippines'],['PCHRD','Philippine Council for Health Research Development'],['PCMH','Philippine Council for Mental Health'],['PFA','Psychological First Aid'],['PGCA','Philippine Guidance Counselling Association'],['PhilHealth','Philippine Health Insurance Corporation'],['PLE','Persons with Lived Experience'],['PMHA','Philippine Mental Health Association'],['PNA','Philippine Neurological Association'],['PPA','Philippine Psychiatric Association']
];
